import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path.home() / ".local/lib"))
import site
sys.path.insert(0, site.getusersitepackages())

from fpdf import FPDF
from fpdf.enums import XPos, YPos

BASE = (Path.home() / "workspace/goals/"
        "cross-gematria-777-gap-filling/files")
MASTER = BASE / "PLATE-IX-GEORGIAN.md"
OUTPUT = BASE / "PLATE-IX-GEORGIAN-MAGVS.pdf"
LOGO = Path.home() / "workspace/templates/doctrine-logo.png"
FONT_DIR = (BASE.parent / "hidden_files" / "lex-stellarrvm-fonts")
DEJAVU = Path("/usr/share/fonts/truetype/dejavu")
NOTO = Path("/usr/share/fonts/truetype/noto")
CJK_TTC = Path("/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc")

FAMILY = "Lex Stellarrvm"

# member: (source face or ('TTC', index), scripts it carries)
MEMBERS = [
    ("Serif", DEJAVU / "DejaVuSerif.ttf",
     "Latin; Greek incl. polytonic and sampi; Cyrillic incl. the "
     "archaic numeral letters"),
    ("SerifBold", DEJAVU / "DejaVuSerif-Bold.ttf",
     "the bold seat of the Serif member's scripts"),
    ("Oblique", DEJAVU / "DejaVuSansMono-Oblique.ttf",
     "the italic seat (house precedent)"),
    ("Hebrew", NOTO / "NotoSerifHebrew-Regular.ttf",
     "Hebrew, including the final forms"),
    ("Arabic", NOTO / "NotoNaskhArabic-Regular.ttf",
     "Arabic, including tāʾ marbūṭa and the hamza forms"),
    ("Coptic", NOTO / "NotoSansCoptic-Regular.ttf",
     "Coptic, including the Demotic letters in their fenced printings"),
    ("Armenian", NOTO / "NotoSansArmenian-Regular.ttf",
     "Armenian, both cases and the late annex letters"),
    ("Georgian", NOTO / "NotoSansGeorgian-Regular.ttf",
     "Georgian Mkhedruli and Mtavruli"),
    ("Ethiopic", NOTO / "NotoSansEthiopic-Regular.ttf",
     "the Ethiopic syllabary of the classical bases (three derived "
     "syllables excepted — see the font-law note)"),
    ("Glagolitic", NOTO / "NotoSansGlagolitic-Regular.ttf",
     "Glagolitic, both cases"),
    ("Syriac", NOTO / "NotoSansSyriac-Regular.ttf",
     "Syriac — the Aramaic dress named at the Hebrew plate"),
    ("ImperialAramaic", NOTO / "NotoSansImperialAramaic-Regular.ttf",
     "Imperial Aramaic — the Aramaic dress named at the Hebrew plate"),
    ("Japanese", ("TTC", 0),
     "hiragana and katakana (Noto Sans CJK JP, extracted from the "
     "system TTC by this builder)"),
    ("Korean", ("TTC", 1),
     "Hangul syllables and jamo (Noto Sans CJK KR, same extraction)"),
    ("Signs", NOTO / "NotoSans-Regular.ttf",
     "the Cyrillic higher signs (꙰ ꙱ ꙲)"),
    ("Symbols", NOTO / "NotoSansSymbols-Regular.ttf",
     "the combining enclosing circle (U+20DD)"),
    ("Sans", DEJAVU / "DejaVuSans.ttf",
     "the safety net"),
]

UNHELD_TOKENS = {'\u12b1': '[U+12B1]', '\u1311': '[U+1311]',
                 '\u1316': '[U+1316]'}

FOOTER = ("— {n} of {nb} — | All Rights Reserved, Without "
          "Prejudice | Flagpole of Claim and Coinage reserved")

# ---------------------------------------------------------------------
# The print dress — Plate II's §II scheme, letter for letter:
# the master's Hebrew runs by transliteration (the script-forms
# distinguished by capitals). The master's Greek passes
# untouched; the Serif member carries it.
# ---------------------------------------------------------------------
HEBREW_DRESS = {"א": "ʾ", "ב": "b", "ג": "g", "ד": "d", "ה": "h",
                "ו": "w", "ז": "z", "ח": "ḥ", "ט": "ṭ", "י": "y",
                "כ": "k", "ך": "K", "ל": "l", "מ": "m", "ם": "M",
                "נ": "n", "ן": "N", "ס": "s", "ע": "ʿ", "פ": "p",
                "ף": "P", "צ": "ṣ", "ץ": "Ṣ", "ק": "q", "ר": "r",
                "ש": "š", "ת": "t", "־": "-", "׳": "ʾ", "״": '"'}
DRESS = {}
DRESS.update(HEBREW_DRESS)


def transliterate(text):
    """Every right-to-left letter of the master's scripts
    becomes its declared dress; all else passes untouched."""
    return "".join(DRESS.get(ch, ch) for ch in text)


def _rename(font, member, source_label):
    table = font["name"]
    full = f"{FAMILY} {member}"
    ps = f"LexStellarrvm-{member}"
    subfamily = {"Serif": "Regular", "SerifBold": "Bold",
                 "Oblique": "Oblique"}.get(member, "Regular")
    for platform, enc, lang in ((3, 1, 0x409), (1, 0, 0)):
        table.setName(FAMILY, 1, platform, enc, lang)
        table.setName(subfamily, 2, platform, enc, lang)
        table.setName(f"{full}; house composite member; "
                      f"source face: {source_label}",
                      3, platform, enc, lang)
        table.setName(full, 4, platform, enc, lang)
        table.setName(ps, 6, platform, enc, lang)
        table.setName(FAMILY, 16, platform, enc, lang)
        table.setName(member, 17, platform, enc, lang)


def prepare_family():
    """MECHANISM: write the renamed member copies if absent; the
    CJK members are first extracted from the system TTC.
    DOCTRINE: the rename touches the name table only; the
    colophon names each source beside its member."""
    from fontTools.ttLib import TTFont, TTCollection
    FONT_DIR.mkdir(parents=True, exist_ok=True)
    paths = {}
    ttc = None
    for member, source, _scripts in MEMBERS:
        target = FONT_DIR / f"LexStellarrvm-{member}.ttf"
        paths[member] = target
        if target.exists():
            continue
        if isinstance(source, tuple):
            if ttc is None:
                ttc = TTCollection(str(CJK_TTC))
            font = ttc.fonts[source[1]]
            label = f"{CJK_TTC.name} face {source[1]}"
        else:
            font = TTFont(str(source))
            label = source.name
        _rename(font, member, label)
        font.save(str(target))
    return paths


def coverage_audit(paths):
    """Every non-ASCII codepoint of the master against the member
    cmaps. Returns (count, unheld); the build proceeds only if
    the unheld set is within the three named Ethiopic syllables."""
    from fontTools.ttLib import TTFont
    text = MASTER.read_text(encoding="utf-8")
    cps = {ord(c) for c in text if ord(c) > 127}
    held = set()
    for p in paths.values():
        held |= set(TTFont(str(p)).getBestCmap().keys())
    unheld = {c for c in cps if c not in held}
    named = {0x12B1, 0x1311, 0x1316}
    print(f"coverage audit: {len(cps)} codepoints, "
          f"unheld: {sorted(hex(c) for c in unheld)}")
    assert unheld <= named, f"UNHELD beyond the named three: {unheld}"
    return len(cps), unheld


class PlatesPDF(FPDF):
    def footer(self):
        self.set_y(-14)
        self.set_font(FAMILY, "", 8)
        self.cell(0, 8, FOOTER.format(n=self.page_no(), nb="{nb}"),
                  align="C")


def clean(text):
    text = transliterate(text)
    for a, b in UNHELD_TOKENS.items():
        text = text.replace(a, b)
    return text.replace("**", "").replace("*", "")


def main():
    paths = prepare_family()
    n_cps, unheld = coverage_audit(paths)
    lines = MASTER.read_text(encoding="utf-8").splitlines()

    pdf = PlatesPDF(orientation="P", unit="mm", format="Letter")
    pdf.set_auto_page_break(auto=True, margin=18)
    pdf.set_margins(20, 16, 20)
    pdf.alias_nb_pages("{nb}")
    pdf.add_font(FAMILY, "", str(paths["Serif"]))
    pdf.add_font(FAMILY, "B", str(paths["SerifBold"]))
    pdf.add_font(FAMILY, "I", str(paths["Oblique"]))
    fallbacks = []
    for member, _s, _c in MEMBERS:
        if member in ("Serif", "SerifBold", "Oblique"):
            continue
        key = "lex" + member.lower()
        pdf.add_font(key, "", str(paths[member]))
        # MECHANISM: the fallback faces are also registered
        # under the bold and italic styles, pointing at the
        # same files — fpdf2 resolves a missing glyph against
        # the CURRENT style's fallbacks, and this plate's
        # headings may carry a fallback script in bold,
        # where an unregistered style drops the glyph. The
        # member's regular face answers for its bold: a
        # mechanical substitution, declared here.
        pdf.add_font(key, "B", str(paths[member]))
        pdf.add_font(key, "I", str(paths[member]))
        fallbacks.append(key)
    pdf.set_fallback_fonts(fallbacks)
    pdf.add_page()

    def para(text, size=10.5, style="", align="L", space=2.2,
             indent=0):
        pdf.set_font(FAMILY, style, size)
        if indent:
            pdf.set_x(pdf.l_margin + indent)
        pdf.multi_cell(pdf.epw - indent, 5.4, text, align=align,
                       new_x=XPos.LMARGIN, new_y=YPos.NEXT)
        pdf.ln(space)

    def heading(text, size, space_before=5):
        pdf.ln(space_before)
        pdf.set_font(FAMILY, "B", size)
        pdf.multi_cell(0, size * 0.62, text, align="L",
                       new_x=XPos.LMARGIN, new_y=YPos.NEXT)
        pdf.ln(2.4)

    i = 0
    while i < len(lines):
        raw = lines[i]
        line = raw.strip()
        i += 1
        if not line:
            continue
        if line.startswith("!["):
            w = 42
            pdf.image(str(LOGO), x=(pdf.w - w) / 2, w=w)
            pdf.ln(4)
            continue
        if line == "---":
            pdf.ln(2)
            continue
        if line.startswith("**PLATE IX"):
            pdf.set_font(FAMILY, "B", 19)
            pdf.multi_cell(0, 9.5, clean(line), align="C",
                           new_x=XPos.LMARGIN, new_y=YPos.NEXT)
            pdf.ln(2)
            continue
        if line.startswith(("*Subtitle:*",
                            "Authorship attributed",
                            "XXIV day of",
                            "Classification:",
                            "Method of Science",
                            "Flagpole of Claim")):
            para(clean(line), align="C", space=1.2)
            continue
        if line.startswith("#### "):
            heading(clean(line[5:]), 11.5)
            continue
        if line.startswith("### "):
            heading(clean(line[4:]), 12)
            continue
        if line.startswith("## "):
            title = clean(line[3:])
            if "— PLATE" in title:
                # Each plate opens on its own page, head first.
                pdf.add_page()
                pdf.set_font(FAMILY, "B", 13.5)
                pdf.multi_cell(0, 13.5 * 0.62, title, align="L",
                               new_x=XPos.LMARGIN,
                               new_y=YPos.NEXT)
                pdf.ln(2.4)
            else:
                heading(title, 13.5)
            continue
        if line.startswith("# "):
            pdf.set_font(FAMILY, "B", 19)
            pdf.multi_cell(0, 9.5, clean(line[2:]), align="C",
                           new_x=XPos.LMARGIN, new_y=YPos.NEXT)
            pdf.ln(2)
            continue
        if line.startswith("|"):
            rows = []
            while i <= len(lines) and line.startswith("|"):
                cells = [c.strip()
                         for c in line.strip("|").split("|")]
                if not all(set(c) <= set("-: ") for c in cells):
                    rows.append("  ·  ".join(clean(c)
                                             for c in cells))
                if i < len(lines):
                    line = lines[i].strip()
                    i += 1
                else:
                    break
            for r in rows:
                para(r, size=8.6, space=1.1, indent=3)
            pdf.ln(1.5)
            continue
        if line.startswith("> "):
            para(clean(line[2:]), size=11, style="I", align="C",
                 indent=8)
            continue
        if line.startswith("- "):
            para("•  " + clean(line[2:]), indent=5)
            continue
        if re.match(r"^\d+\. ", line):
            para(clean(line), indent=5)
            continue
        buf = [line]
        while i < len(lines):
            nxt = lines[i].strip()
            if not nxt or nxt.startswith(("#", "|", ">", "- ",
                                           "---")) \
                    or re.match(r"^\d+\. ", nxt):
                break
            buf.append(nxt)
            i += 1
        para(clean(" ".join(buf)))

    pdf.add_page()
    heading("Colophon of the MAGVS Seat — the Lex Stellarrvm "
            "Family", 13.5)
    para("This PDF is set throughout in the Lex Stellarrvm "
         "family, the Founder's house family, named under his "
         "Flagpole of Claim and Coinage. The family is a "
         "composite: its members are the faces named below, "
         "each carrying the scripts listed beside it, all "
         "registered under the one family name — new members "
         "added under the same family, as the Founder directed. "
         "The family name is his; the member faces are named "
         "as what they are, never passed off as a single "
         "foundry font.")
    for member, source, scripts in MEMBERS:
        label = (f"{CJK_TTC.name} face {source[1]}"
                 if isinstance(source, tuple) else source.name)
        para(f"LexStellarrvm-{member} — source face: "
             f"{label}. Carries: {scripts}.", indent=5)
    para("The print dress of this plate: the plate's own "
         "script is Georgian and prints as itself, in the "
         "family's Georgian member — in all three of its "
         "dresses: Mkhedruli, Asomtavruli and Nuskhuri "
         "stand in their own signs throughout, in the "
         "bank, the registers, and the calibration heads, "
         "and the Mtavruli headline letter of the fold "
         "exhibit stands in its own sign likewise. The "
         "control case's Armenian stands in the family's "
         "Armenian member. The master's Greek stands in "
         "the family's Serif member, as on Plate I. The "
         "master's Hebrew runs — the frame register's "
         "words of record — are carried in this PDF by "
         "transliteration, under Plate II's declared "
         "scheme, the script-forms the script distinguishes "
         "distinguished by capitals (the five final forms "
         "as K, M, N, P and Ṣ) — the toolchain not shaping "
         "right-to-left scripts honestly. The substitutions "
         "are marked and declared; the Markdown master "
         "keeps the scripts themselves, entire.")
    token_note = (
        " Three Ethiopic syllables — [U+12B1], [U+1311], "
        "[U+1316] — are drawn by no member (no Noto Ethiopic "
        "face, the upstream included, draws them); where "
        "this master carries them — named in §VI's font-law "
        "sentence — they print as the codepoint tokens "
        "shown here, named, never silently dropped.")
    para(f"Font coverage was audited against every non-ASCII "
         f"codepoint in the master before this build: {n_cps} "
         f"distinct codepoints." + token_note +
         " No glyph is silently dropped.")
    para("Method of Science. Aim of Religion.")
    para("Flagpole of Claim and Coinage: Johnathan 'Qasparr' "
         "Monroe, ARR, All Rights Reserved, Without Prejudice. "
         "Right of claim hereby reserved and coined under the "
         "authority of the Living Man.")
    para("93 — Live, Love, and let Love, Live.")

    pdf.output(str(OUTPUT))
    print(f"built {OUTPUT} — {pdf.pages_count} pages")
    return 0


if __name__ == "__main__":
    sys.exit(main())
